// Deterministic refresh-token rotation server with reuse detection.
// No Date/Math.random: token names come from a fixed counter.
function makeServer() {
  let counter = 1;
  const used = new Set();      // refresh tokens already exchanged
  const next = new Map();      // RTold -> RTnew (supersession chain)
  let revoked = false;         // whole family burned?

  function mint() { return "RT" + (counter++); }

  // returns { ok, rt?, reason? }
  function refresh(rt) {
    if (revoked) return { ok: false, reason: "family_revoked" };
    if (used.has(rt)) {
      // replay of an already-rotated token => burn everything
      revoked = true;
      return { ok: false, reason: "replay_detected" };
    }
    used.add(rt);
    const fresh = mint();
    next.set(rt, fresh);
    return { ok: true, rt: fresh };
  }
  return { refresh, firstToken: mint };
}

const srv = makeServer();
const RT1 = srv.firstToken();   // issued at login => RT1
const log = [];

// 1) legit client refreshes RT1 -> RT2
let r = srv.refresh(RT1);
log.push(`client RT1 -> ${r.ok ? r.rt : "FAIL:" + r.reason}`);
const RT2 = r.rt;

// 2) legit client refreshes RT2 -> RT3
r = srv.refresh(RT2);
log.push(`client RT2 -> ${r.ok ? r.rt : "FAIL:" + r.reason}`);
const RT3 = r.rt;

// 3) ATTACKER replays the stolen RT1 (already used) => replay detected
r = srv.refresh(RT1);
log.push(`attacker RT1 -> ${r.ok ? r.rt : "FAIL:" + r.reason}`);

// 4) legit client tries RT3 (was valid!) but family is now revoked
r = srv.refresh(RT3);
log.push(`client RT3 -> ${r.ok ? r.rt : "FAIL:" + r.reason}`);

console.log(log.join("\n"));

